type TabSelectorProps = { options: { id: string; label: string; count?: number }[]; value: string; onChange: (id: string) => void };

export const TabSelector_MIN = {"base":[8,2]};

export function TabSelector(props: TabSelectorProps) {
  const { options, value, onChange } = props;
  const uid = useRef("tabselector-" + Math.random().toString(36).slice(2)).current;
  const [hover, setHover] = useState<string | null>(null);
  const [flash, setFlash] = useState(0);

  useEffect(() => {
    setFlash((f) => f + 1);
  }, [value]);

  const floor = TabSelector_MIN.base;

  return (
    <div
      className="h-full w-full relative"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      <div className="absolute inset-0 rounded-md border border-cyan-500/20 bg-[#07070c] shadow-[inset_0_2px_8px_rgba(0,0,0,0.8)] overflow-hidden">
        <div className="absolute inset-0 opacity-40 bg-[linear-gradient(90deg,rgba(6,182,212,0.12)_0%,rgba(217,70,239,0.06)_100%)]" />
        <div
          key={"scan-" + flash}
          className="absolute inset-y-0 w-1/3 pointer-events-none bg-[linear-gradient(90deg,transparent_0%,rgba(253,224,71,0.10)_50%,transparent_100%)]"
          style={{ animation: "tabselectorSweep 700ms ease-out 1 forwards" }}
        />
        <style>{"@keyframes tabselectorSweep{0%{transform:translateX(-120%)}100%{transform:translateX(420%)}}"}</style>

        {options.length === 0 ? (
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="font-mono tracking-wider uppercase text-[10px] text-slate-500">no categories</span>
          </div>
        ) : (
          <div className="absolute inset-0 flex items-stretch gap-1 p-1 overflow-x-auto overflow-y-hidden [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
            {options.map((o) => {
              const active = o.id === value;
              const hot = hover === o.id && !active;
              return (
                <button
                  key={uid + "-" + o.id}
                  type="button"
                  onPointerEnter={() => setHover(o.id)}
                  onPointerLeave={() => setHover(null)}
                  onClick={() => onChange(o.id)}
                  className={
                    "group relative flex-1 min-w-0 flex items-center justify-center gap-2 px-2 rounded-sm border transition-all duration-200 ease-out touch-none " +
                    (active
                      ? "bg-yellow-300 border-yellow-300/70 shadow-[0_0_16px_rgba(253,224,71,0.4)] -translate-y-px"
                      : hot
                      ? "bg-cyan-500/20 border-cyan-400/60"
                      : "bg-transparent border-cyan-500/20")
                  }
                  style={{ clipPath: "polygon(0 0, calc(100% - 0.45rem) 0, 100% 0.45rem, 100% 100%, 0.45rem 100%, 0 calc(100% - 0.45rem))" }}
                >
                  <span
                    className={
                      "min-w-0 truncate font-mono font-bold uppercase text-[10px] tracking-[0.18em] transition-colors duration-200 " +
                      (active ? "text-black" : hot ? "text-cyan-100" : "text-slate-400")
                    }
                  >
                    {o.label}
                  </span>
                  {typeof o.count === "number" ? (
                    <span
                      className={
                        "shrink truncate rounded-sm border px-1 font-mono text-[10px] leading-none tracking-wide transition-all duration-200 " +
                        (active
                          ? "border-black/40 bg-black/20 text-black"
                          : "border-fuchsia-500/40 bg-fuchsia-500/15 text-fuchsia-400")
                      }
                    >
                      {o.count}
                    </span>
                  ) : null}
                  <span
                    className={
                      "pointer-events-none absolute left-0 bottom-0 h-[2px] bg-cyan-400 transition-all duration-300 ease-out " +
                      (active ? "w-0 opacity-0" : hot ? "w-full opacity-100" : "w-0 opacity-0")
                    }
                  />
                  {active ? (
                    <span className="pointer-events-none absolute inset-0 rounded-sm ring-2 ring-fuchsia-400/60 animate-pulse" />
                  ) : null}
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

type MapRouteProps = { points: { x: number; y: number }[]; animated?: boolean };

export const MapRoute_MIN = {"base":[2,2]};

export function MapRoute(props: MapRouteProps) {
  const uid = useRef("maproute-" + Math.random().toString(36).slice(2)).current;
  const pts = props.points || [];
  const animated = !!props.animated;

  const d = useMemo(() => {
    if (pts.length < 2) return "";
    return pts
      .map((p, i) => (i === 0 ? "M " : "L ") + (p.x * 100).toFixed(3) + " " + (p.y * 100).toFixed(3))
      .join(" ");
  }, [pts]);

  const floor = MapRoute_MIN.base;

  return (
    <div
      className="h-full w-full pointer-events-none"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      {d ? (
        <svg
          className="absolute inset-0 h-full w-full"
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          style={{ position: "absolute", overflow: "visible" }}
        >
          <defs>
            <linearGradient id={uid + "-grad"} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="#22d3ee" />
              <stop offset="55%" stopColor="#facc15" />
              <stop offset="100%" stopColor="#e879f9" />
            </linearGradient>
            <filter id={uid + "-glow"} x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation="2" result="b" />
              <feMerge>
                <feMergeNode in="b" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
            <path id={uid + "-path"} d={d} />
          </defs>

          {/* outer halo */}
          <path
            d={d}
            fill="none"
            stroke="#22d3ee"
            strokeOpacity="0.18"
            strokeWidth="9"
            strokeLinejoin="round"
            strokeLinecap="round"
            vectorEffect="non-scaling-stroke"
            filter={"url(#" + uid + "-glow)"}
          />
          {/* dark casing */}
          <path
            d={d}
            fill="none"
            stroke="#07070c"
            strokeOpacity="0.85"
            strokeWidth="5.5"
            strokeLinejoin="round"
            strokeLinecap="round"
            vectorEffect="non-scaling-stroke"
          />
          {/* core line */}
          <path
            d={d}
            fill="none"
            stroke={"url(#" + uid + "-grad)"}
            strokeWidth="2.4"
            strokeLinejoin="round"
            strokeLinecap="round"
            vectorEffect="non-scaling-stroke"
          />
          {/* dashed energy overlay */}
          <path
            d={d}
            fill="none"
            stroke="#fde047"
            strokeOpacity={animated ? 0.95 : 0.35}
            strokeWidth="1.2"
            strokeLinecap="round"
            strokeDasharray="6 10"
            vectorEffect="non-scaling-stroke"
          >
            {animated ? (
              <animate
                attributeName="stroke-dashoffset"
                from="16"
                to="0"
                dur="0.9s"
                repeatCount="indefinite"
              />
            ) : null}
          </path>

          {/* node pips */}
          {pts.map((p, i) => (
            <circle
              key={"pip-" + i}
              cx={p.x * 100}
              cy={p.y * 100}
              r="1"
              fill="#0a0a0f"
              stroke={i === 0 ? "#22d3ee" : i === pts.length - 1 ? "#fde047" : "#e879f9"}
              strokeWidth="2"
              vectorEffect="non-scaling-stroke"
            />
          ))}

          {/* traveling pulse */}
          {animated ? (
            <g filter={"url(#" + uid + "-glow)"}>
              <circle r="2" fill="#fde047">
                <animateMotion dur="3.2s" repeatCount="indefinite" rotate="auto">
                  <mpath href={"#" + uid + "-path"} />
                </animateMotion>
                <animate
                  attributeName="r"
                  values="1.4;2.6;1.4"
                  dur="0.8s"
                  repeatCount="indefinite"
                />
              </circle>
            </g>
          ) : null}
        </svg>
      ) : null}
    </div>
  );
}

type StatDetailPanelProps = {
  entries: { label: string; value: string | number; delta?: number; tone?: "neutral" | "positive" | "negative" }[];
  title?: string;
  visible?: boolean;
};

export const StatDetailPanel_MIN = {"base":[9,4.5]};

export function StatDetailPanel(props: StatDetailPanelProps) {
  const { entries, title, visible } = props;
  const uid = useRef("statdetailpanel-" + Math.random().toString(36).slice(2)).current;
  const shown = visible !== false;
  const floor = StatDetailPanel_MIN.base;

  const toneText = (t?: string) =>
    t === "positive" ? "text-lime-400" : t === "negative" ? "text-red-500" : "text-cyan-50";

  const deltaMeta = (d: number) => {
    if (d > 0) return { c: "text-lime-400 border-lime-400/40 bg-lime-500/15", s: "+" };
    if (d < 0) return { c: "text-red-500 border-red-500/40 bg-red-500/15", s: "" };
    return { c: "text-slate-500 border-slate-500/30 bg-slate-500/10", s: "" };
  };

  return (
    <div
      className="h-full w-full"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      <div
        className={
          "relative h-full w-full overflow-hidden rounded-lg border border-cyan-400/30 " +
          "bg-[linear-gradient(135deg,rgba(21,15,40,0.9)_0%,rgba(10,10,20,0.95)_100%)] backdrop-blur-sm " +
          "shadow-[0_0_20px_rgba(34,211,238,0.15),0_0_40px_rgba(217,70,239,0.08)] " +
          "transition-all duration-200 ease-out " +
          (shown ? "opacity-100 translate-y-0 blur-0" : "opacity-0 translate-y-1 blur-[2px] pointer-events-none")
        }
      >
        {/* corner ticks */}
        <div className="pointer-events-none absolute inset-0">
          <div className="absolute left-0 top-0 h-3 w-3 border-l-2 border-t-2 border-yellow-300/70" />
          <div className="absolute right-0 bottom-0 h-3 w-3 border-r-2 border-b-2 border-fuchsia-500/50" />
          <div className="absolute inset-0 opacity-[0.12] bg-[repeating-linear-gradient(0deg,rgba(34,211,238,0.6)_0px,rgba(34,211,238,0.6)_1px,transparent_1px,transparent_4px)]" />
        </div>

        <div className="relative flex h-full w-full flex-col">
          {title ? (
            <div className="flex h-9 w-full items-center gap-2 border-b border-cyan-400/30 px-3 bg-[linear-gradient(90deg,rgba(6,182,212,0.15)_0%,rgba(217,70,239,0.08)_100%)]">
              <span className="h-2 w-2 rotate-45 bg-yellow-300 shadow-[0_0_8px_rgba(253,224,71,0.8)]" />
              <span className="min-w-0 truncate font-mono text-xs font-bold uppercase tracking-[0.25em] text-cyan-100 drop-shadow-[0_0_6px_rgba(34,211,238,0.5)]">
                {title}
              </span>
            </div>
          ) : null}

          <div className="min-h-0 flex-1 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
            {entries.length === 0 ? (
              <div className="flex h-full w-full items-center justify-center px-3">
                <span className="font-mono text-[10px] uppercase tracking-wider text-slate-500">
                  no data
                </span>
              </div>
            ) : (
              <div className="flex w-full flex-col">
                {entries.map((e, i) => {
                  const d = e.delta;
                  const hasD = typeof d === "number" && isFinite(d);
                  const dm = hasD ? deltaMeta(d as number) : null;
                  return (
                    <div
                      key={uid + "-row-" + i}
                      className={
                        "group flex w-full items-center gap-2 border-b border-cyan-500/10 p-2 " +
                        "transition-all duration-200 ease-out hover:bg-cyan-500/10"
                      }
                      style={{ animation: "none" }}
                    >
                      <span className="min-w-0 flex-1 truncate font-mono text-[10px] font-medium uppercase tracking-wider text-slate-400">
                        {e.label}
                      </span>
                      <span
                        className={
                          "min-w-0 truncate font-mono text-sm font-black tracking-tight " +
                          toneText(e.tone) +
                          (e.tone === "positive"
                            ? " drop-shadow-[0_0_6px_rgba(163,230,53,0.5)]"
                            : e.tone === "negative"
                            ? " drop-shadow-[0_0_6px_rgba(239,68,68,0.5)]"
                            : " drop-shadow-[0_0_6px_rgba(34,211,238,0.35)]")
                        }
                      >
                        {e.value}
                      </span>
                      {hasD && dm ? (
                        <span
                          className={
                            "shrink truncate rounded-sm border px-2 py-1 font-mono text-[10px] font-bold leading-none tracking-wider " +
                            dm.c
                          }
                        >
                          {dm.s}
                          {d}
                        </span>
                      ) : null}
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          <div className="flex h-7 w-full items-center justify-between border-t border-cyan-500/20 bg-black/50 px-3">
            <span className="font-mono text-[10px] uppercase tracking-wider text-cyan-400/70">
              {entries.length > 0 ? entries.length + " stats" : "—"}
            </span>
            <span className="flex items-center gap-1">
              {[0, 1, 2].map((k) => (
                <span
                  key={uid + "-dot-" + k}
                  className="h-1 w-3 bg-cyan-400/50"
                  style={{ opacity: 0.25 + k * 0.3 }}
                />
              ))}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

