export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + body(7 slots x 3.25 = 22.75 + 6 gaps x 0.5 = 3 => 25.75) + padding 1 + footer 1.75 = 30.75 ≤ 34.7
  // BUDGET width: pad 1 + slots col 13 + gap 0.75 + preview 15 + gap 0.75 + detail col 13 = 43.5 ≤ 52.0

  type Rarity = "common" | "uncommon" | "rare" | "epic" | "legendary";
  type Item = {
    id: string;
    name: string;
    rarity: Rarity;
    armor: number;
    price: number;
    stats: { label: string; value: string | number; delta?: number }[];
  };

  const initial: { slotId: string; group: "WEAPONS" | "ARMOR"; label: string; item?: Item }[] = [
    {
      slotId: "primary",
      group: "WEAPONS",
      label: "PRIMARY",
      item: {
        id: "w1",
        name: "ACHILLES 7.62",
        rarity: "legendary",
        armor: 0,
        price: 14200,
        stats: [
          { label: "DPS", value: 412.6, delta: 38 },
          { label: "RPM", value: 620 },
          { label: "CRIT DMG", value: "+41%", delta: 12 },
          { label: "HANDLING", value: "B+", delta: -4 },
        ],
      },
    },
    {
      slotId: "secondary",
      group: "WEAPONS",
      label: "SECONDARY",
      item: {
        id: "w2",
        name: "LEXINGTON TC",
        rarity: "rare",
        armor: 0,
        price: 3900,
        stats: [
          { label: "DPS", value: 188.2, delta: -6 },
          { label: "RPM", value: 480 },
          { label: "MAG", value: 24 },
        ],
      },
    },
    {
      slotId: "melee",
      group: "WEAPONS",
      label: "MELEE",
      item: {
        id: "w3",
        name: "MANTIS BLADES",
        rarity: "epic",
        armor: 0,
        price: 9100,
        stats: [
          { label: "DMG", value: 264 },
          { label: "BLEED", value: "+55%", delta: 21 },
          { label: "STAMINA", value: -8, delta: -8 },
        ],
      },
    },
    {
      slotId: "head",
      group: "ARMOR",
      label: "HEAD",
      item: {
        id: "a1",
        name: "NETRUNNER VISOR",
        rarity: "rare",
        armor: 84,
        price: 2400,
        stats: [
          { label: "ARMOR", value: 84, delta: 14 },
          { label: "RAM", value: "+2", delta: 2 },
        ],
      },
    },
    {
      slotId: "torso",
      group: "ARMOR",
      label: "TORSO",
      item: {
        id: "a2",
        name: "AR-VEST MK.III",
        rarity: "epic",
        armor: 162,
        price: 6800,
        stats: [
          { label: "ARMOR", value: 162, delta: 40 },
          { label: "RESIST/PHYS", value: "+18%", delta: 18 },
          { label: "WEIGHT", value: 7.2, delta: -1 },
        ],
      },
    },
    {
      slotId: "legs",
      group: "ARMOR",
      label: "LEGS",
      item: {
        id: "a3",
        name: "CORPO SLACKS",
        rarity: "common",
        armor: 41,
        price: 350,
        stats: [
          { label: "ARMOR", value: 41, delta: -9 },
          { label: "COOL", value: "+1", delta: 1 },
        ],
      },
    },
    { slotId: "feet", group: "ARMOR", label: "FEET" },
  ];

  const [slots, setSlots] = useState(initial);
  const [selected, setSelected] = useState<string>("primary");
  const [eddies, setEddies] = useState(28450);
  const [flash, setFlash] = useState<null | "buy" | "sell">(null);
  const [log, setLog] = useState("LOADOUT SYNCED // NET-LINK STABLE");

  const current = slots.find((s) => s.slotId === selected);
  const armorTotal = useMemo(
    () => slots.reduce((a, s) => a + (s.item ? s.item.armor : 0), 0),
    [slots]
  );

  const pulse = (k: "buy" | "sell") => {
    setFlash(k);
    setTimeout(() => setFlash(null), 600);
  };

  const buy = () => {
    if (!current) return;
    if (current.item) return;
    const restock: Item = {
      id: "new-" + current.slotId,
      name: "TECH BOOTS X9",
      rarity: "uncommon",
      armor: 52,
      price: 1250,
      stats: [
        { label: "ARMOR", value: 52, delta: 52 },
        { label: "MOVE SPD", value: "+6%", delta: 6 },
      ],
    };
    setEddies((e) => e - restock.price);
    setSlots((s) => s.map((x) => (x.slotId === current.slotId ? { ...x, item: restock } : x)));
    setLog("PURCHASE // -" + restock.price + " €$ // " + restock.name);
    pulse("buy");
  };

  const sell = () => {
    if (!current || !current.item) return;
    const it = current.item;
    setEddies((e) => e + Math.round(it.price * 0.4));
    setSlots((s) => s.map((x) => (x.slotId === current.slotId ? { ...x, item: undefined } : x)));
    setLog("SOLD // +" + Math.round(it.price * 0.4) + " €$ // " + it.name);
    pulse("sell");
  };

  const rarityText: Record<Rarity, string> = {
    common: "text-slate-300",
    uncommon: "text-lime-400",
    rare: "text-sky-400",
    epic: "text-fuchsia-400",
    legendary: "text-yellow-300",
  };

  const entries = current?.item
    ? [
        ...current.item.stats.map((st) => ({
          label: st.label,
          value: st.value,
          delta: st.delta,
          tone:
            st.delta === undefined
              ? ("neutral" as const)
              : st.delta >= 0
              ? ("positive" as const)
              : ("negative" as const),
        })),
        { label: "VALUE", value: current.item.price + " €$", tone: "neutral" as const },
      ]
    : [{ label: "SLOT", value: "EMPTY", tone: "negative" as const }];

  const layers = slots
    .filter((s) => s.item)
    .map((s) => ({ id: s.item!.id, slot: s.slotId }));

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-zinc-950 bg-[radial-gradient(ellipse_at_top,#1a0b2e_0%,#0a0a0f_60%)] text-cyan-50">
      <div className="h-9 flex-none flex items-center justify-between px-3 border-b border-cyan-400/30 bg-[linear-gradient(90deg,rgba(6,182,212,0.15)_0%,rgba(217,70,239,0.08)_100%)]">
        <span className="font-mono font-bold tracking-[0.25em] uppercase text-cyan-100 drop-shadow-[0_0_6px_rgba(34,211,238,0.5)] text-sm truncate">
          Loadout // Gear Manifest
        </span>
        <span className="font-mono font-black tracking-tight text-yellow-300 drop-shadow-[0_0_8px_rgba(253,224,71,0.6)] text-sm">
          {eddies.toLocaleString()} €$
