export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + counters 3 + gap .75 + attr list 9 + gap .75 + bars 5×1.25=6.25 + gap .75 + spend controls 3 + footer 1.75 = 27.5 ≤ 38.1
  // BUDGET width: pad .75 + left col 24 + gap .75 + right col 25.5 + pad .75 = 51.75 ≤ 52.0

  const BASE: Record<string, number> = { body: 6, reflexes: 5, tech: 4, int: 7, cool: 5 };

  type Attr = { id: string; label: string; sublabel: string; value: number };
  const [attrs, setAttrs] = useState<Attr[]>([
    { id: "body", label: "BODY", sublabel: "Health · Armor · Melee", value: 9 },
    { id: "reflexes", label: "REFLEXES", sublabel: "Stamina · Evasion", value: 7 },
    { id: "tech", label: "TECHNICAL ABILITY", sublabel: "Crafting · Armor Plating", value: 4 },
    { id: "int", label: "INTELLIGENCE", sublabel: "RAM · Quickhacks", value: 11 },
    { id: "cool", label: "COOL", sublabel: "Crit · Stealth", value: 5 },
  ]);
  const [selected, setSelected] = useState("body");
  const [points, setPoints] = useState(6);
  const [perkPoints, setPerkPoints] = useState(9);
  const [flash, setFlash] = useState<string | null>(null);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [selPerk, setSelPerk] = useState<string>("");

  type Perk = { id: string; label: string; detail: string; rank: number; max: number; req: number };
  const [perks, setPerks] = useState<Record<string, Perk[]>>({
    body: [
      { id: "b1", label: "PAINKILLER", detail: "Health regen +50% in combat", rank: 1, max: 3, req: 5 },
      { id: "b2", label: "WOLVERINE", detail: "Regen rate scales with Body", rank: 0, max: 2, req: 9 },
      { id: "b3", label: "JUGGERNAUT", detail: "Armor +6% per rank", rank: 2, max: 3, req: 7 },
      { id: "b4", label: "UNSHAKABLE", detail: "Immune to stagger", rank: 0, max: 1, req: 15 },
      { id: "b5", label: "QUAKE", detail: "Ground slam shockwave", rank: 0, max: 2, req: 18 },
    ],
    reflexes: [
      { id: "r1", label: "SLIPPERY", detail: "Evasion +10%", rank: 1, max: 2, req: 4 },
      { id: "r2", label: "AIR DASH", detail: "Dash mid-air once", rank: 0, max: 1, req: 7 },
      { id: "r3", label: "MITIGATE", detail: "Reduce incoming dmg 15%", rank: 0, max: 3, req: 12 },
      { id: "r4", label: "DASH CHAIN", detail: "Consecutive dashes cost less", rank: 0, max: 2, req: 15 },
    ],
    tech: [
      { id: "t1", label: "GLUTTON FOR WAR", detail: "Cyberware charge +20%", rank: 0, max: 2, req: 4 },
      { id: "t2", label: "RENAISSANCE PUNK", detail: "+1 to all attributes", rank: 0, max: 1, req: 9 },
      { id: "t3", label: "EDGERUNNER", detail: "Exceed cyberware capacity", rank: 0, max: 1, req: 20 },
    ],
    int: [
      { id: "i1", label: "RAM RECLAMATION", detail: "Recover RAM over time", rank: 2, max: 3, req: 5 },
      { id: "i2", label: "OVERCLOCK", detail: "Spend Health as RAM", rank: 1, max: 1, req: 9 },
      { id: "i3", label: "EMBEDDED PROTOCOL", detail: "Quickhack spread +2 targets", rank: 0, max: 2, req: 11 },
      { id: "i4", label: "SUBLIMINAL MSG", detail: "Uploads are untraceable", rank: 0, max: 2, req: 15 },
    ],
    cool: [
      { id: "c1", label: "NINJUTSU", detail: "Crouched crit chance +15%", rank: 1, max: 3, req: 4 },
      { id: "c2", label: "DEADEYE", detail: "Headshot dmg +25%", rank: 0, max: 2, req: 9 },
      { id: "c3", label: "GHOST", detail: "Detection speed -30%", rank: 0, max: 2, req: 12 },
    ],
  });

  const cur = attrs.find((a) => a.id === selected)!;
  const ping = (k: string) => { setFlash(k); setTimeout(() => setFlash(null), 450); };

  const spend = () => {
    if (points <= 0 || cur.value >= 20) return;
    setAttrs((p) => p.map((a) => (a.id === selected ? { ...a, value: a.value + 1 } : a)));
    setPoints((p) => p - 1);
    ping("attr");
  };
  const refund = () => {
    if (cur.value <= BASE[selected]) return;
    setAttrs((p) => p.map((a) => (a.id === selected ? { ...a, value: a.value - 1 } : a)));
    setPoints((p) => p + 1);
    ping("attr");
  };

  const buyPerk = (id: string) => {
    const list = perks[selected];
    const perk = list.find((p) => p.id === id);
    if (!perk || perkPoints <= 0 || perk.rank >= perk.max || perk.req > cur.value) return;
    setPerks((prev) => ({ ...prev, [selected]: prev[selected].map((p) => (p.id === id ? { ...p, rank: p.rank + 1 } : p)) }));
    setPerkPoints((p) => p - 1);
    ping("perk");
  };

  const attrOptions = attrs.map((a) => ({
    id: a.id,
    label: a.label,
    sublabel: a.sublabel,
    meta: a.value,
    tone: (a.id === selected ? "accent" : "neutral") as "accent" | "neutral",
  }));

  const perkOptions = (perks[selected] || []).map((p) => ({
    id: p.id,
    label: p.label,
    detail: p.detail,
    sublabel: "REQ " + p.req,
    meta: p.rank + "/" + p.max,
    locked: p.req > cur.value,
    tone: (p.rank > 0 ? "accent" : "neutral") as "accent" | "neutral",
  }));

  const toneFor = (id: string) => (id === "body" ? "danger" : id === "int" ? "accent" : id === "cool" ? "neutral" : "warning");

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-zinc-950 bg-[radial-gradient(ellipse_at_top,#1a0b2e_0%,#0a0a0f_60%)] text-cyan-50">
      {/* header */}
      <div className="h-9 flex-none flex items-center justify-between px-3 border-b border-cyan-400/30 bg-[linear-gradient(90deg,rgba(6,182,212,0.15)_0%,rgba(217,70,239,0.08)_100%)]">
        <span className="font-mono font-bold tracking-[0.25em] uppercase text-cyan-100 text-sm drop-shadow-[0_0_6px_rgba(34,211,238,0.5)]">
          Character · Attributes
        </span>
        <span className="font-mono tracking-[0.2em] uppercase text-[10px] text-fuchsia-400 animate-pulse">◈ build v2.1</span>
      </div>

      <div className="flex-1 flex flex-row gap-3 p-3">
        {/* LEFT */}
        <div className="flex flex-col gap-3" style={{ width: "24rem" }}>
          {/* counters */}
          <div className="flex flex-row gap-2">
            {[
              { k: "attr", label: "Attribute Points", v: points, tone: "accent" as const },
              { k: "perk", label: "Perk Points", v: perkPoints, tone: "neutral" as const },
            ].map((c) => (
              <div
                key={c.k}
                className={
                  "flex-1 flex items-center gap-2 rounded-md border border-cyan-500/20 bg-[#07070c] shadow-[inset_0_2px_8px_rgba(0,0,0,0.8)] px-2 py-1 transition-all duration-200 " +
                  (flash === c.k ? "ring-2 ring-fuchsia-400/60 animate-pulse" : "")
                }
              >
                <div style={{ width: "3.25rem", height: "2rem" }}>
                  <NumericReadout value={c.v} animate tone={c.tone} />
                </div>
                <span className="font-mono font-medium tracking-wider uppercase text-[10px] leading-none text-slate-400">{c.label}</span>
              </div>
            ))}
          </div>

          {/* attribute list */}
          <div style={{ height: "9.5rem" }}>
            <SelectionList options={attrOptions} value={selected} onChange={(id) => { setSelected(id); setSelPerk(""); }} />
